    fun updateRule(rule: Store.Rule?, visibleMonth: compat.time.YearMonth?) {
        if (((rule!!.id) <= 0)) {
            throw (IllegalArgumentException("הוראת הקבע אינה קיימת"))
        }
        var d: android.database.sqlite.SQLiteDatabase? = writableDatabase
        d!!.beginTransaction()
        try {
            var through: compat.time.YearMonth? = visibleMonth
            (d!!.rawQuery("SELECT MAX(date) FROM transactions WHERE rule=?", arrayOf<String>(("" + rule!!.id)!!))).use { c ->
                if ((c!!.moveToFirst() && !(c!!.isNull(0)))) {
                    var last: compat.time.YearMonth? = compat.time.YearMonth.from((compat.time.LocalDate.parse((c!!.getString(0))!!))!!)
                    if ((last!!.isAfter(through!!))) {
                        through = last
                    }
                }
            }
            save(rule)
            rememberWhere("transactions", "rule=? AND status=0", arrayOf<String>(("" + rule!!.id)!!))
            d!!.delete("transactions", "rule=? AND status=0", arrayOf<String>(("" + rule!!.id)!!))
            dirty()
            ensureMonth(through)
            d!!.setTransactionSuccessful()
        } finally {
            d!!.endTransaction()
        }
    }
    fun setRuleActive(r: Store.Rule?, active: Boolean) {
        var d: android.database.sqlite.SQLiteDatabase? = writableDatabase
