            save(r)
            if ((!active)) {
                rememberWhere("transactions", "rule=? AND status=0 AND date>=?", arrayOf<String>(("" + r!!.id)!!, (compat.time.LocalDate.now()!!.toString())!!))
                d!!.delete("transactions", "rule=? AND status=0 AND date>=?", arrayOf<String>(("" + r!!.id)!!, (compat.time.LocalDate.now()!!.toString())!!))
                dirty()
            }
            d!!.setTransactionSuccessful()
        } finally {
            d!!.endTransaction()
        }
    }
    fun ensureMonth(month: compat.time.YearMonth?) {
        refreshCache()
        if ((compat.j.Objects.equals(ensured!!.get(month!!), GEN!!.get()))) {
            return
        }
        var d: android.database.sqlite.SQLiteDatabase? = writableDatabase
        d!!.beginTransaction()
        try {
            for (r in rules()!!) {
                if (((r!!.active) == 1)) {
                    var existingMonths: MutableSet<String>? = HashSet<String>()
                    (d!!.rawQuery("SELECT substr(date,1,7) FROM transactions WHERE rule=?", arrayOf<String>(("" + r!!.id)!!))).use { c ->
                        while ((c!!.moveToNext())) {
                            existingMonths!!.add((c!!.getString(0))!!)
                        }
                    }
                    var start: compat.time.LocalDate? = compat.time.LocalDate.parse((r!!.start)!!)
                    run {
                        var instance: compat.time.YearMonth? = compat.time.YearMonth.from(start!!)
                        while (!(instance!!.isAfter(month!!))) {
                            try {
                                var date: compat.time.LocalDate? = Finance.day(instance, start!!.dayOfMonth)
                                if ((date!!.isBefore(start!!) || (!(((r!!.end)!!.javaTrim())!!.isEmpty()) && date!!.isAfter((compat.time.LocalDate.parse((r!!.end)!!))!!)))) {
                                    continue
                                }
                                if ((existingMonths!!.contains((instance!!.toString())!!))) {
                                    continue
                                }
                                var v: android.content.ContentValues? = android.content.ContentValues()
                                v!!.put("date", date!!.toString())
                                v!!.put("amount", expectedRuleAmount(r))
                                v!!.put("original_amount", r!!.originalAmount)
                                v!!.put("currency", r!!.currency)
                                v!!.put("fx_rate", r!!.fxRate)
                                v!!.put("fx_fee", (if ("ILS".equals(r!!.currency)) "0" else (account(r!!.account))!!.fxFee))
                                v!!.put("fx_date", r!!.fxDate)
                                v!!.put("fx_source", r!!.fxSource)
                                v!!.put("category", r!!.category)
                                v!!.put("merchant", r!!.name)
                                v!!.put("note", "")
                                v!!.put("tag", "")
                                v!!.put("account", r!!.account)
                                v!!.put("kind", "expense")
                                v!!.put("count", 1)
                                v!!.put("status", 0)
                                v!!.put("rule", r!!.id)
                                var created: Long = d!!.insertWithOnConflict("transactions", null, v!!, android.database.sqlite.SQLiteDatabase.CONFLICT_IGNORE)
                                if ((created > 0)) {
                                    rememberNew("transactions", created)
                                    dirty()
                                }
                            } finally {
                                instance = instance!!.plusMonths((r!!.interval).toLong())
                            }
                        }
                    }
                }
            }
            d!!.setTransactionSuccessful()
        } finally {
            d!!.endTransaction()
        }
        ensured!!.put(month!!, GEN!!.get())
    }
    fun creditCycleTransactions(a: Store.Account?, month: compat.time.YearMonth?): MutableList<Store.Tx>? {
        var from: compat.time.LocalDate? = Finance.creditCycleStart(month, a!!.closing)
