    fun cumulative(selected: compat.time.YearMonth?, today: compat.time.LocalDate?): Store.SeriesData? {
        var p: ReportPeriod? = reporting()
        var data: Store.SeriesData? = Store.SeriesData()
        var days: Int = p!!.elapsed(selected, today)
        var current: LongArray? = LongArray(days)
        var previous: LongArray? = LongArray(days)
        var prior: compat.time.YearMonth? = selected!!.minusMonths(1L)
        for (t in transactions()!!) {
            if (((t!!.status) == 1 && isSpending(t))) {
                var date: compat.time.LocalDate? = compat.time.LocalDate.parse((t!!.date)!!)
                var value: Long = netExpense(t)
                var index: Int
                if ((p!!.contains(selected, date))) {
                    index = (compat.time.temporal.ChronoUnit.DAYS!!.between((p!!.start(selected))!!, date!!)).toInt()
                    if ((index < days)) {
                        current!![index] = compat.util.Math.addExact(current!![index], value)
                    }
                } else {
                    if ((p!!.contains(prior, date))) {
                        index = (compat.time.temporal.ChronoUnit.DAYS!!.between((p!!.start(prior))!!, date!!)).toInt()
                        if ((index < days)) {
                            previous!![index] = compat.util.Math.addExact(previous!![index], value)
                        }
                    }
                }
            }
        }
        run {
            var n: Int = 0
            while (n < days) {
                (data!!.labels)!!.add(("" + (n + 1))!!)
                if ((n > 0)) {
                    current!![n] = compat.util.Math.addExact(current!![n], current!![n - 1])
                    previous!![n] = compat.util.Math.addExact(previous!![n], previous!![n - 1])
                }
                n++
            }
        }
        (data!!.series)!!.put("החודש הנבחר", current!!)
        (data!!.series)!!.put("החודש הקודם", previous!!)
        return data
    }
    fun incomeVsExpenses(selected: compat.time.YearMonth?): Store.SeriesData? {
        var data: Store.SeriesData? = Store.SeriesData()
        var income: LongArray? = LongArray(6)
        var expenses: LongArray? = LongArray(6)
        run {
            var n: Int = 0
            while (n < 6) {
                var period: compat.time.YearMonth? = selected!!.minusMonths((5 - n).toLong())
                (data!!.labels)!!.add(((period!!.monthValue).toString() + "/" + ((period!!.year) % 100))!!)
                income!![n] = total(period, "income")
                expenses!![n] = total(period, "expense")
                n++
            }
        }
        (data!!.series)!!.put("הכנסות", income!!)
        (data!!.series)!!.put("הוצאות", expenses!!)
        return data
    }
