    fun charges(month: compat.time.YearMonth?): MutableList<Store.Charge>? {
        var out: MutableList<Store.Charge>? = ArrayList<Store.Charge>()
        var txs: MutableList<Store.Tx>? = transactions()
        for (a in accounts()!!) {
            if ((!((a!!.billingHistory)!!.equals("[]")))) {
                for (due in (billingDates(a, (month!!.atDay(1))!!.minusDays(1L), month!!.atEndOfMonth()))!!) {
                    var paid: Long = (creditState(a, due, txs, true))!!.paid
                    if ((paid > 0)) {
                        out!!.add(Store.Charge(due, paid, a!!.id, 0L, a!!.name + " · פירעון אשראי משוער", true))
                    }
                }
                continue
            }
            if (((a!!.type)!!.equals("fixed") && a!!.cycleConfigured)) {
                var due: compat.time.LocalDate? = Finance.day(month, a!!.charge)
                var paid: Long = (cycleFixedState(a, due, txs, true))!!.paid
                if ((paid > 0)) {
                    out!!.add(Store.Charge(due, paid, a!!.id, 0L, a!!.name + " · חיוב קבוע משוער", true))
                }
            } else {
                if (((a!!.type)!!.equals("fixed"))) {
                    var start: compat.time.YearMonth? = compat.time.YearMonth.from((compat.time.LocalDate.parse((a!!.start)!!))!!)
                    if ((month!!.isBefore(start!!))) {
                        continue
                    }
                    var balance: Long = a!!.opening
                    run {
                        var m: compat.time.YearMonth? = start
                        while (!(m!!.isAfter(month!!))) {
                            var due: compat.time.LocalDate? = Finance.day(m, a!!.charge)
                            for (t in txs!!) {
                                if (((t!!.account) == (a!!.id))) {
                                    balance = balance + (fixedAccrual(t, m, true, due))
                                }
                            }
                            var payment: Long = Finance.fixedPayment(balance, a!!.payment)
                            balance = balance - payment
                            if ((m!!.equals(month!!) && payment > 0)) {
                                out!!.add(Store.Charge(due, payment, a!!.id, 0L, a!!.name + " · חיוב קבוע משוער", true))
                            }
                            for (t in txs!!) {
                                if (((t!!.account) == (a!!.id))) {
                                    balance = balance + (fixedAccrual(t, m, false, due))
                                }
                            }
                            m = m!!.plusMonths(1L)
                        }
                    }
                } else {
                    if (((a!!.type)!!.equals("credit") && (a!!.openingPayment) > 0)) {
                        var due: compat.time.LocalDate? = Finance.day(month, a!!.charge)
                        var start: compat.time.LocalDate? = compat.time.LocalDate.parse((a!!.start)!!)
                        var paid: Long = (Finance.openingRemaining(a!!.opening, a!!.openingPayment, start, a!!.charge, due!!.minusDays(1L))) - (Finance.openingRemaining(a!!.opening, a!!.openingPayment, start, a!!.charge, due))
                        if ((paid > 0)) {
                            out!!.add(Store.Charge(due, paid, a!!.id, 0L, a!!.name + " · פירעון ניצול קודם", true))
                        }
                    }
                    for (t in txs!!) {
                        if (((t!!.account) == (a!!.id))) {
                            var date: compat.time.LocalDate? = (if (!((t!!.firstDue)!!.isEmpty())) compat.time.LocalDate.parse((t!!.firstDue)!!) else (if ((t!!.kind)!!.equals("income")) compat.time.LocalDate.parse((t!!.date)!!) else Finance.due(compat.time.LocalDate.parse((t!!.date)!!), a!!.type, a!!.closing, a!!.charge)))
                            var index: Int = (compat.time.temporal.ChronoUnit.MONTHS!!.between((compat.time.YearMonth.from(date!!))!!, month!!)).toInt()
                            if ((index >= 0 && index < (t!!.count))) {
                                var due: compat.time.LocalDate? = Finance.day(month, (if ((a!!.type)!!.equals("credit") && (t!!.firstDue)!!.isEmpty() && !((t!!.kind)!!.equals("income"))) a!!.charge else date!!.dayOfMonth))
                                var amount: Long = Finance.installment(t!!.amount, t!!.count, index)
                                if ((!((t!!.kind)!!.equals("expense")))) {
                                    amount = -amount
                                }
                                var charge: Store.Charge? = Store.Charge(due, amount, a!!.id, t!!.id, (if (((t!!.merchant)!!.javaTrim())!!.isEmpty()) t!!.category else t!!.merchant), (t!!.status) == 0)
                                charge!!.kind = t!!.kind
                                out!!.add(charge!!)
                            }
                        }
                    }
                }
            }
        }
        out!!.javaSort((compat.j.Comparators.comparing((compat.j.Function<Store.Charge, compat.time.LocalDate> l8@{ c -> (c!!.date)!! })!!))!!)
        return out
    }
    fun creditUsage(a: Store.Account?, asOf: compat.time.LocalDate?): Long {
        if ((!(isCredit(a)))) {
            return 0L
