    private fun legacyCreditUsage(a: Store.Account?, asOf: compat.time.LocalDate?, txs: MutableList<Store.Tx>?, forecast: Boolean): Long {
        var start: compat.time.LocalDate? = compat.time.LocalDate.parse((a!!.start)!!)
        if (((a!!.type)!!.equals("fixed"))) {
            if ((a!!.cycleConfigured)) {
                return (cycleFixedState(a, asOf, txs, forecast))!!.total()
            }
            if ((asOf!!.isBefore(start!!))) {
                return 0L
            }
            var purchases: compat.j.TreeMap<compat.time.LocalDate, Long>? = compat.j.TreeMap<compat.time.LocalDate, Long>()
            for (t in txs!!) {
                var date: compat.time.LocalDate? = compat.time.LocalDate.parse((t!!.date)!!)
                if (((t!!.account) == (a!!.id) && (forecast || (t!!.status) == 1) && isSpending(t) && !(date!!.isBefore(start!!)) && !(date!!.isAfter(asOf!!)))) {
                    purchases!!.put(date!!, compat.util.Math.addExact((purchases!!.javaGetOrDefault(date!!, 0L))!!, netExpense(t)))
                }
            }
            run {
                var m: compat.time.YearMonth? = compat.time.YearMonth.from(start!!)
                while (!(m!!.isAfter((compat.time.YearMonth.from(asOf!!))!!))) {
                    var due: compat.time.LocalDate? = Finance.day(m, a!!.charge)
                    if ((!(due!!.isBefore(start!!)) && !(due!!.isAfter(asOf!!)))) {
                        purchases!!.javaPutIfAbsent(due!!, 0L)
                    }
                    m = m!!.plusMonths(1L)
                }
            }
            var balance: Long = a!!.opening
            for (event in (purchases!!.entries)!!) {
                balance = compat.util.Math.addExact(balance, (event!!.value)!!)
                if (((event!!.key)!!.equals((Finance.day(compat.time.YearMonth.from((event!!.key)!!), a!!.charge))!!))) {
                    balance = balance - (Finance.fixedPayment(balance, a!!.payment))
                }
            }
